#!/usr/bin/env -S deno run -A
import { conditions, job, step, workflow } from "jsr:@david/gagen@^0.5.0";

const pluginName = "zig";

const isTag = conditions.isTag();

const getTagVersion = step({
  id: "get_tag_version",
  name: "Get tag version",
  if: isTag,
  run: `echo "TAG_VERSION=\${GITHUB_REF/refs\\/tags\\//}" >> "$GITHUB_OUTPUT"`,
  outputs: ["TAG_VERSION"],
});

const buildJob = job("build", {
  name: "build",
  runsOn: "ubuntu-latest",
  timeoutMinutes: 30,
  // gh release create needs this, even where the repo's token defaults to read
  permissions: { contents: "write" },
  steps: [
    { uses: "actions/checkout@v6" },
    // installs the minimum_zig_version of build.zig.zon, which build.zig requires exactly
    { uses: "mlugg/setup-zig@v2" },
    { uses: "denoland/setup-deno@v2", with: { "deno-version": "v2.x" } },

    { name: "Check formatting", run: "zig fmt --check build.zig build.zig.zon main.zig src tests/spec_test.zig" },
    // the spec tests compare the plugin to this zig's `zig fmt`
    { name: "Test", run: "zig build test --summary all" },
    { name: "Build", run: "zig build" },
    {
      name: "Lint workflow generation",
      run: [
        "./.github/workflows/ci.ts --lint",
        "./.github/workflows/publish_npm.ts --lint",
        "./.github/workflows/release.ts --lint",
        "./.github/workflows/check_updates.ts --lint",
      ],
    },

    // NPM
    { uses: "actions/setup-node@v6", with: { "node-version": "24.x" } },
    {
      name: "Check the plugin has no imports",
      run:
        `node -e "const m = new WebAssembly.Module(require('fs').readFileSync('zig-out/plugin.wasm')); const imports = WebAssembly.Module.imports(m); if (imports.length > 0) { console.error(imports); process.exit(1); }"`,
    },
    {
      name: "Setup and test npm deployment",
      run: [
        "cd deployment/npm",
        "npm install",
        "node setup.js",
        "npm run test",
      ],
    },

    getTagVersion,

    // GITHUB RELEASE
    {
      name: "Pre-release",
      if: isTag,
      run: [
        `test "$(cat VERSION)" = "${getTagVersion.outputs.TAG_VERSION}" || (echo "The VERSION file doesn't match the tag" && exit 1)`,
        "# update config schema to have version",
        `sed -i 's/dprint-plugin-${pluginName}\\/0.0.0/dprint-plugin-${pluginName}\\/${getTagVersion.outputs.TAG_VERSION}/' deployment/schema.json`,
        "# create release notes",
        `deno run -A ./scripts/generateReleaseNotes.ts ${getTagVersion.outputs.TAG_VERSION} > \${{ github.workspace }}-CHANGELOG.txt`,
      ],
    },
    {
      name: "Release",
      if: isTag,
      // gh uploads the assets to a draft and then publishes it, which immutable releases require
      env: { GH_TOKEN: "${{ secrets.GITHUB_TOKEN }}" },
      run: [
        `gh release create "$GITHUB_REF_NAME" --verify-tag --title "$GITHUB_REF_NAME"`,
        "--notes-file ${{ github.workspace }}-CHANGELOG.txt",
        "zig-out/plugin.wasm",
        "deployment/schema.json",
      ].join(" \\\n  "),
    },
  ],
});

workflow({
  name: "CI",
  on: {
    pull_request: { branches: ["main"] },
    push: { branches: ["main"], tags: ["*"] },
  },
  jobs: [buildJob],
}).writeOrLint({
  filePath: new URL("./ci.generated.yml", import.meta.url),
  header: "# GENERATED BY ./ci.ts -- DO NOT DIRECTLY EDIT",
  pinDeps: true,
});
